import{_ as a,o as s,c as n,a4 as i}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20251010180204579.BdQtV1pR.png",o="/assets/image-20251010180713227.CSK9-850.png",r="/assets/image-20251010180910601.BisGRO16.png",l="/assets/wanshaoweixin.DWzIcicW.jpg",u=JSON.parse('{"title":"开发者注意了 DevEco Studio 6 Release 开放了，但是我劝你慎重升级6应用","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/开发者注意了 DevEco Studio 6 Release 开放了，但是我劝你慎重升级6应用/开发者注意了 DevEco Studio 6 Release 开放了，但是我劝你慎重升级6应用.md","filePath":"鸿蒙开发技巧/开发者注意了 DevEco Studio 6 Release 开放了，但是我劝你慎重升级6应用/开发者注意了 DevEco Studio 6 Release 开放了，但是我劝你慎重升级6应用.md","lastUpdated":1760850507000,"__rawMarkdown":"# 开发者注意了 DevEco Studio 6 Release 开放了，但是我劝你慎重升级6应用\\n\\n## 前言\\n\\n早在9月25号，鸿蒙就发布了 **DevEco Studio 6 Release**了，意味着广大开发者直接使用它开发和打包应用了。\\n\\n![image-20251010180204579](assets/image-20251010180204579.png)\\n\\n## 需要注意的事\\n\\n这个当然个好事，这样我们开发者就不需要使用一台电脑上同时安装两个开发工具了，之前我们是这样做的\\n\\n1. `DevEco Studio 5`  用来打包上架应用\\n2. `DevEco Studio 6 Beta`  用来开发和体验 鸿蒙6新特性，但是因为是Beta版本的编辑器，那么是无法使用它打包应用提交上架的，会被打回。\\n\\n但是对于这一类小伙伴需要慎重使用 **DevEco Studio 6 Release** 打包应用。\\n\\n## 开发新应用参加 激励赛 的小伙伴\\n\\n参加2025激励赛的小伙伴想要拿到激励活动，除了上架新应用之外，新应用还需要达到月活才行\\n\\n![image-20251010180713227](assets/image-20251010180713227.png)\\n\\n想象一下，如果你直接发布的新应用是HarmonyOS 6的，那么就意味着 HarmonyOS 5版本的手机都无法使用你的应用，那么你的月活不就难达到了吗\\n\\n## 参加激励赛的小伙伴\\n\\n同样的，对于参加激励赛的小伙伴，按照最新要求，是必须要上架HarmonyOS 6版本的\\n\\n![image-20251010180910601](assets/image-20251010180910601.png)\\n\\n这个时候小伙伴也会面临着升级的问题，\\n\\n那么能不能做到HarmonyOS5的手机用户使用旧版本的应用，\\n\\nHarmonyOS6的手机用户使用新版本也就是HarmonyOS6的应用呢？\\n\\n答案就是 **compatibleSdkVersion**  和  **targetSdkVersion**\\n\\n##  **compatibleSdkVersion**  和  **targetSdkVersion**\\n\\n1. compatibleSdkVersion：应用/元服务运行所需兼容的最低SDK版本\\n2. targetSdkVersion：应用/元服务运行所需目标SDK版本\\n\\n通俗的讲你希望你的应用运行在最低版本是API14的手机上，同时最高版本是API20的手机上，那么你可以这样配置\\n\\n```json\\n\\"targetSdkVersion\\": \\"6.0.0(20)\\",\\n\\"compatibleSdkVersion\\": \\"5.0.2(14)\\",\\n```\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多HarmonyOS相关的资讯。\\n\\n![](assets/wanshaoweixin.jpg)"}'),d={name:"鸿蒙开发技巧/开发者注意了 DevEco Studio 6 Release 开放了，但是我劝你慎重升级6应用/开发者注意了 DevEco Studio 6 Release 开放了，但是我劝你慎重升级6应用.md"};function p(c,e,h,m,g,S){return s(),n("div",null,[...e[0]||(e[0]=[i("",26)])])}const _=a(d,[["render",p]]);export{u as __pageData,_ as default};
